mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM counseling_reservations
    WHERE user_id = #{userId}
      AND training_id = #{trainingId}
      AND status != '취소'
)

mapper.update:
UPDATE counseling_reservations
SET latest_message = #{latestMessage},
    latest_at = #{latestAt}
WHERE room_id = #{roomId}

UPDATE counseling_reservations
SET status = #{status}
WHERE room_id = #{roomId}

